import { WORLD_WIDTH, WORLD_HEIGHT } from './constants';

// The background is drawn with "cover" scaling centered on the world,
// so mirror that math when mapping world coordinates to mask cells.
const IMG_W = 1920;
const IMG_H = 1088;
const SCALE = Math.max(WORLD_WIDTH / IMG_W, WORLD_HEIGHT / IMG_H);
const DRAW_W = IMG_W * SCALE;
const DRAW_H = IMG_H * SCALE;
const OFFSET_X = (DRAW_W - WORLD_WIDTH) / 2;
const OFFSET_Y = (DRAW_H - WORLD_HEIGHT) / 2;

export function isL1Blocked(x: number, y: number): boolean {
  const c = Math.floor(((x + OFFSET_X) / DRAW_W) * L1_COLS);
  const r = Math.floor(((y + OFFSET_Y) / DRAW_H) * L1_ROWS);
  if (c < 0 || r < 0 || c >= L1_COLS || r >= L1_ROWS) return true;
  return L1_MASK[r][c] === 1;
}
